const theme=useTheme();
const {smAndDown}=useDisplay();
const navigationOpen=ref(!smAndDown.value);
watch(smAndDown,small=>{navigationOpen.value=!small;});
watch([activeThemeName,activeThemeDefinition],()=>{
 // Update the editable Vuetify registry and root tokens together, including teleported UI.
 const definition=activeThemeDefinition.value;
 const base=theme.themes.value[definition.dark?'dark':'light'];
 theme.themes.value[activeThemeName.value] = {...base,dark:!!definition.dark,colors:{...base.colors,...definition.colors},variables:{...base.variables}};
 applyPaletteCss();
 void theme.change(activeThemeName.value);
},{immediate:true,deep:true});
function changeAppearance(event:Event){const value=(event.target as HTMLSelectElement).value;if(isThemePreference(value))void saveAppearance(value).catch(error=>toast(String(error.message)));}
const db=ref<Database>({components:[],systems:[],configurations:[],pcs:[],inventory:[],requirementsSets:[],installationLocations:[]});
const transitionsWorkspace=ref<InstanceType<typeof TransitionsWorkspace>|null>(null);
const settingsWorkspace=ref<{hasUnsavedChanges:()=>boolean;confirmDiscard:()=>boolean}|null>(null);
const identifySource=ref<string|null>(null),identifyEditor=ref<InstanceType<typeof ComponentIdentificationDialog>|null>(null);
const mergeSources=ref<string[]|null>(null),mergeEditor=ref<InstanceType<typeof ComponentMergeDialog>|null>(null);
const catalogMaintenance=ref<InstanceType<typeof CatalogMaintenance>|null>(null);
const installationsWorkspace=ref<InstanceType<typeof InstallationsWorkspace>|null>(null);
const inventoryWorkspace=ref<InstanceType<typeof InventoryWorkspace>|null>(null);
const recoveryRequired=ref(false);
const revision=ref(''), editorRevision=ref(''), configRevision=ref(''), editorOriginal=ref('');
const restoreFile=ref<File|null>(null), restorePreview=ref<{counts:Record<string,number>;revision:string;transitionPlans:number;archivedInventory:number;backupRevision:string}|null>(null), restoreBackup=ref<unknown>(null), spreadsheetSafe=ref(true);
const loading=ref(true), failure=ref(''), busy=ref(false), notices=ref<string[]>([]);
const refreshEpoch=ref(0);
function closeMobileNav(){if(!smAndDown.value)return;navigationOpen.value=false;nextTick(()=>document.getElementById('mobile-nav-toggle')?.focus());}
const catalogView=ref('components'),familyFilter=ref(''),familyGrouped=ref(false),duplicateModelsOnly=ref(false);
const familyKey=(c:Component)=>JSON.stringify([c.manufacturer.trim().toLowerCase(),c.family?.trim().toLowerCase()||'']);
const familyChoices=computed(()=>[...new Map(db.value.components.filter(c=>c.family?.trim()).map(c=>[familyKey(c),{title:`${c.manufacturer||'Manufacturer unknown'} · ${c.family}`,value:familyKey(c)}])).values()].sort((a,b)=>a.title.localeCompare(b.title)));
const duplicateModels=computed(()=>new Set(duplicateModelGroups(db.value.components).flatMap(group=>group.map(c=>c.id))));
const equipmentLocationFilter=ref(''),equipmentDescendants=ref(true),equipmentGrouped=ref(true);
const equipmentLocationChoices=computed(()=>[{title:'All locations',value:''},{title:'Unlinked locations',value:'__unlinked'},...db.value.installationLocations.map(location=>({title:locationPath(location.id,db.value),value:location.id}))]);
const page=ref('Configurations'), search=ref(''), filter=ref('All configurations'), categoryFilter=ref('All components');
const {jobs:catalogQueueJobs,running:catalogQueueRunning,loaded:catalogQueueLoaded,error:catalogQueueError,refresh:refreshCatalogQueue}=useEnrichmentQueue(()=>page.value==='Component catalog');
const catalogMissingCount=computed(()=>db.value.components.filter(needsCatalogAttention).length);
const working=ref<Configuration|null>(null), original=ref(''), detailTab=ref('components');
const componentDraft=ref<Component|null>(null), systemDraft=ref<System|null>(null), pcDraft=ref<InventoryPC|null>(null);
// Activators restore focus only; record buttons already open these dialogs.
// Enabling Vuetify click toggling makes a repeated click close the new draft.
const dialogOpeners=new Map<string,HTMLElement>();
const componentForm=ref<InstanceType<typeof VForm>|null>(null),systemForm=ref<InstanceType<typeof VForm>|null>(null),pcForm=ref<InstanceType<typeof VForm>|null>(null),configurationForm=ref<InstanceType<typeof VForm>|null>(null);
const requiredRule=(value:unknown)=>!!String(value??'').trim()||'A value is required.';
const quantityRule=(value:unknown)=>Number.isInteger(Number(value))&&Number(value)>=1&&Number(value)<=32||'Enter a whole quantity from 1 to 32.';
async function validateRootForm(form:InstanceType<typeof VForm>|null,event?:PromiseLike<{valid:boolean}>){if(!form)return false;const {valid}=event?await event:await form.validate();if(!valid){await nextTick();const input=(form.$el as HTMLElement).querySelector<HTMLElement>('.v-input--error input, .v-input--error textarea, .v-input--error button');const panel=input?.closest('[role=tabpanel]');if(panel?.id.startsWith('configuration-panel-')){detailTab.value=panel.id.slice('configuration-panel-'.length);await nextTick();}input?.focus();}return valid;}
function restoreDialogFallback(name:string){if(!dialogOpeners.get(name)?.isConnected)document.getElementById('main-content')?.focus();dialogOpeners.delete(name);}
for(const [name,draft] of Object.entries({componentDraft,systemDraft,pcDraft}))watch(draft,(value,old)=>{if(value&&!old&&document.activeElement instanceof HTMLElement&&document.activeElement!==document.body&&document.activeElement!==document.documentElement)dialogOpeners.set(name,document.activeElement);},{flush:'sync'});
const confirmDelete=ref<{collection:string;id:string;name:string}|null>(null);
watch(confirmDelete,(value,old)=>{if(value&&!old&&document.activeElement instanceof HTMLElement&&document.activeElement!==document.body&&document.activeElement!==document.documentElement)dialogOpeners.set('delete',document.activeElement);},{flush:'sync'});
const deleteComponentUses=computed(()=>confirmDelete.value?.collection==='components'?componentUsage(confirmDelete.value.id,db.value):[]);
const deleteBlockingUses=computed(()=>confirmDelete.value?.collection==='components'?componentDeletionBlockers(confirmDelete.value.id,db.value):[]);
function emptyStockReference(use:ReturnType<typeof componentUsage>[number]){const stock=use.kind==='stock'?db.value.inventory.find(s=>s.id===use.id):undefined;return !!stock&&stock.quantity===0&&!stock.allocations.length;}
async function archiveEmptyReference(use:ReturnType<typeof componentUsage>[number]){if(busy.value||!emptyStockReference(use))return;busy.value=true;try{await api(`/api/inventory/${encodeURIComponent(use.id)}`,{method:'DELETE',headers:{'If-Match':revision.value}});await load();toast('Empty stock record deleted. History remains in Deleted records.');}catch(e){toast(String(e));await load();}finally{busy.value=false;}}
function openDeleteReference(use:ReturnType<typeof componentUsage>[number]){confirmDelete.value=null;if(use.kind==='requirementsSet'){const target=workspaceRoute('Installations');target.view='requirements';void workspaceHistory.navigate(target);}else void openRelated({kind:use.kind,id:use.id});}
const addCategory=ref<Category>('Scientific card'), addPart=ref(''), addQty=ref(1);
const importing=ref(false);
const navigation=[{name:'Configurations',icon:mdiViewDashboardOutline},{name:'Component catalog',icon:mdiMemory},{name:'Component inventory',icon:mdiCubeOutline},{name:'Equipment systems',icon:mdiLan},{name:'PC inventory',icon:mdiDesktopTowerMonitor},{name:'Storage planner',icon:mdiHarddisk},{name:'Configuration transitions',icon:mdiArrowRight},{name:'Installations',icon:mdiLan}];
const uid=()=>crypto.randomUUID();
const clone=<T,>(v:T):T=>v===undefined?v:JSON.parse(JSON.stringify(v));
function toast(text:string){notices.value.push(text);}
async function api(url:string,options:RequestInit={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');const next=r.headers.get('X-Workspace-Revision');if(next)revision.value=next;return result;}
async function load(){try{const state=await api('/api/state');revision.value=state.revision;recoveryRequired.value=!!state.recoveryRequired;const {revision:_,recoveryRequired:__,...data}=state;db.value=data;failure.value='';}catch(e){failure.value=String(e);}finally{loading.value=false;}}
async function saveRecord(collection:string,record:{id:string},expected=editorRevision.value){if(busy.value)return false;busy.value=true;try{await api(`/api/${collection}/${record.id}`,{method:'PUT',headers:{'If-Match':expected},body:JSON.stringify(record)});await load();if(collection!=='configurations'&&configRevision.value===expected)configRevision.value=revision.value;return true;}catch(e){toast(String(e));return false;}finally{busy.value=false;}}
function confirmWorkspaceDiscard(){
 const workspaces=[identifyEditor.value,mergeEditor.value,transitionsWorkspace.value,recordTable2.value,recordTable3.value,settingsWorkspace.value,catalogMaintenance.value,installationsWorkspace.value,inventoryWorkspace.value];
 if(busy.value||importing.value)return false;
 if((dirty.value||editorDirty.value)&&!window.confirm('Discard unsaved configuration or record changes?'))return false;
 if(!workspaces.every(workspace=>!workspace||workspace.confirmDiscard()))return false;componentDraft.value=null;systemDraft.value=null;pcDraft.value=null;return true;
}
function navigate(name:string){void workspaceHistory.navigate(workspaceRoute(name as RoutePage));}
function changeCatalogView(view:string){if(view===catalogView.value)return;if(catalogMaintenance.value&&!catalogMaintenance.value.confirmDiscard())return;if(recordTable2.value&&!recordTable2.value.confirmDiscard())return;catalogView.value=view;}
type ViewContext={familyFilter?:string;familyGrouped?:boolean;duplicateModelsOnly?:boolean;componentEditor?:ReturnType<InstanceType<typeof ComponentDataEditor>['getContext']>;equipmentLocationFilter?:string;equipmentDescendants?:boolean;equipmentGrouped?:boolean;page:string;search:string;filter:string;categoryFilter:string;catalogView?:string;catalogTable?:ReturnType<InstanceType<typeof RecordTable>['getContext']>;storageTable?:ReturnType<InstanceType<typeof RecordTable>['getContext']>;catalog?:ReturnType<InstanceType<typeof CatalogMaintenance>['getContext']>;configurationId?:string;detailTab:string;inventory?:ReturnType<InstanceType<typeof InventoryWorkspace>['getContext']>;installation?:ReturnType<InstanceType<typeof InstallationsWorkspace>['getContext']>;transition?:ReturnType<InstanceType<typeof TransitionsWorkspace>['getContext']>;scroll:number};
const relatedTrail=ref<ViewContext[]>([]);
function captureView():ViewContext{return {familyFilter:familyFilter.value,familyGrouped:familyGrouped.value,duplicateModelsOnly:duplicateModelsOnly.value,componentEditor:componentDataEditor.value?.getContext(),equipmentLocationFilter:equipmentLocationFilter.value,equipmentDescendants:equipmentDescendants.value,equipmentGrouped:equipmentGrouped.value,page:page.value,search:search.value,filter:filter.value,categoryFilter:categoryFilter.value,catalogView:catalogView.value,catalogTable:recordTable2.value?.getContext(),storageTable:recordTable3.value?.getContext(),catalog:catalogMaintenance.value?.getContext(),configurationId:working.value?.id,detailTab:detailTab.value,inventory:inventoryWorkspace.value?.getContext(),installation:installationsWorkspace.value?.getContext(),transition:transitionsWorkspace.value?.getContext(),scroll:window.scrollY};}
function readRoute():WorkspaceRoute {
 const route=workspaceRoute(page.value as RoutePage);
 if(page.value==='Configurations'&&working.value){route.id=db.value.configurations.some(c=>c.id===working.value?.id)?working.value.id:'new';route.view=detailTab.value;}
 else if(page.value==='Component catalog')route.view=catalogView.value;
 else if(page.value==='PC inventory'||page.value==='Component inventory'){const context=inventoryWorkspace.value?.getContext();route.id=(page.value==='PC inventory'?context?.pcId:context?.stockId)||'';if(route.id)route.view=(page.value==='PC inventory'?context?.tab:context?.stockTab)||route.view;}
 else if(page.value==='Installations'){const context=installationsWorkspace.value?.getContext();route.view=context?.tab||'locations';route.id=route.view==='locations'?context?.locationId||'':'';}
 else if(page.value==='Configuration transitions')route.id=transitionsWorkspace.value?.getContext().planId||'';
 const editor=componentDraft.value?'component':systemDraft.value?'system':pcDraft.value?'pc':'';
 if(editor){const draft=componentDraft.value||systemDraft.value||pcDraft.value;const records=editor==='component'?db.value.components:editor==='system'?db.value.systems:db.value.pcs;route.editor=editor;route.editorId=records.some(r=>r.id===draft?.id)?draft!.id:'new';if(editor==='component')route.editorView=componentDataEditor.value?.getContext().section||'basics';}
 return route;
}
function canLeaveRoute(from:WorkspaceRoute,to:WorkspaceRoute){
 if(busy.value||importing.value)return false;
 if(from.page!==to.page||from.id!==to.id)return confirmWorkspaceDiscard();
 if(from.editor==='component'&&to.editor==='component'&&from.editorId===to.editorId&&from.editorView!==to.editorView&&!componentDataEditor.value?.canChangeSection())return false;
 if(from.editor!==to.editor||from.editorId!==to.editorId){if(editorDirty.value&&!window.confirm('Discard unsaved changes in this editor?'))return false;}
 if(from.page==='Component catalog'&&from.view!==to.view){if(catalogMaintenance.value&&!catalogMaintenance.value.confirmDiscard())return false;if(recordTable2.value&&!recordTable2.value.confirmDiscard())return false;}
 if(from.page==='Installations'&&from.view!==to.view&&installationsWorkspace.value&&!installationsWorkspace.value.confirmDiscard())return false;
 return true;
}
async function applyRoute(route:WorkspaceRoute,historyContext?:unknown){
 const context=historyContext as ViewContext|undefined,previous=readRoute();
 relatedTrail.value=[];
 if(previous.page!==route.page||previous.id!==route.id)working.value=null;
 if(previous.editor!==route.editor||previous.editorId!==route.editorId){componentDraft.value=null;systemDraft.value=null;pcDraft.value=null;}
 page.value=route.page;catalogView.value=route.page==='Component catalog'?route.view:'components';
 equipmentLocationFilter.value=context?.equipmentLocationFilter||'';equipmentDescendants.value=context?.equipmentDescendants??true;equipmentGrouped.value=context?.equipmentGrouped??true;
 familyFilter.value=context?.familyFilter||'';familyGrouped.value=context?.familyGrouped??false;duplicateModelsOnly.value=context?.duplicateModelsOnly??false;search.value=context?.search||'';filter.value=context?.filter||'All configurations';categoryFilter.value=context?.categoryFilter||'All components';
 if(route.page==='Configurations'){
  if(!route.id)working.value=null;
  else if(!working.value){const configuration=db.value.configurations.find(c=>c.id===route.id);if(configuration)openConfig(configuration);else if(route.id==='new')newConfig();else toast('Configuration not found. It may have been deleted.');}
  detailTab.value=route.view;
 }
 await nextTick();
 if(route.page==='PC inventory'||route.page==='Component inventory'){
  const inventory=inventoryWorkspace.value;if(inventory){const settings={...inventory.getContext(),...(context?.inventory||{}),pcId:route.page==='PC inventory'?route.id:'',stockId:route.page==='Component inventory'?route.id:'',tab:route.page==='PC inventory'?route.view:'parts',stockTab:route.page==='Component inventory'?route.view:'allocations'};
   if(settings.pcId&&!db.value.pcs.some(p=>p.id===settings.pcId)){toast('PC not found.');settings.pcId='';}if(settings.stockId&&!db.value.inventory.some(stock=>stock.id===settings.stockId)){toast('Stock record not found.');settings.stockId='';}
   inventory.restoreContext(settings);
  }
 }
 if(route.page==='Installations'&&installationsWorkspace.value){const installation=installationsWorkspace.value;const locationId=route.id&&db.value.installationLocations.some(l=>l.id===route.id)?route.id:'';if(route.id&&!locationId)toast('Installation location not found.');installation.restoreContext({...installation.getContext(),...(context?.installation||{}),tab:route.view,locationId});}
 if(route.page==='Component catalog'&&context?.catalogTable)recordTable2.value?.restoreContext(context.catalogTable);
 if(route.page==='Storage planner'&&context?.storageTable)recordTable3.value?.restoreContext(context.storageTable);
 if(route.page==='Component catalog'&&catalogMaintenance.value)catalogMaintenance.value.restoreContext({...catalogMaintenance.value.getContext(),...(context?.catalog||{}),tab:route.view});
 if(route.page==='Configuration transitions'&&(previous.page!==route.page||previous.id!==route.id))await transitionsWorkspace.value?.openRoute(route.id,context?.transition);
 if(route.editor&&!componentDraft.value&&!systemDraft.value&&!pcDraft.value){
  if(route.editor==='component'){const component=db.value.components.find(c=>c.id===route.editorId);if(component||route.editorId==='new')editComponent(component);else toast('Component not found.');}
  else if(route.editor==='system'){const system=db.value.systems.find(s=>s.id===route.editorId);if(system||route.editorId==='new')editSystem(system);else toast('Equipment system not found.');}
  else {const pc=db.value.pcs.find(p=>p.id===route.editorId);if(pc||route.editorId==='new')editPC(pc);else toast('PC not found.');}
 }
 await nextTick();if(route.editor==='component')componentDataEditor.value?.restoreContext(context?.componentEditor,route.editorView||'basics');
 if(smAndDown.value)navigationOpen.value=false;
 await nextTick();document.getElementById('main-content')?.focus();window.scrollTo(0,context?.scroll||0);
}
async function openRelated(record:RelatedRecord){
 const collection={pc:db.value.pcs,stock:db.value.inventory,configuration:db.value.configurations,location:db.value.installationLocations,component:db.value.components}[record.kind];
 if(!collection.some(item=>item.id===record.id)){toast('This related record no longer exists. Reload the workspace.');return;}
 const context=captureView(),trail=[...relatedTrail.value];
 const target=workspaceRoute({pc:'PC inventory',stock:'Component inventory',configuration:'Configurations',location:'Installations',component:'Component catalog'}[record.kind] as RoutePage);
 if(record.kind==='component'){target.editor='component';target.editorId=record.id;}else target.id=record.id;
 if(await workspaceHistory.navigate(target))relatedTrail.value=[...trail,context];
}
async function backToRelated(){
 const trail=[...relatedTrail.value],context=trail.at(-1);if(!context)return;const target=workspaceRoute(context.page as RoutePage);
 if(context.configurationId){target.id=context.configurationId;target.view=context.detailTab;}
 else if(context.inventory){target.id=target.page==='PC inventory'?context.inventory.pcId:context.inventory.stockId;target.view=target.page==='PC inventory'?context.inventory.tab:context.inventory.stockTab;}
 else if(context.installation){target.view=context.installation.tab;target.id=context.installation.locationId;}
 else if(context.transition)target.id=context.transition.planId;
 else if(target.page==='Component catalog')target.view=context.catalogView||'components';
 if(await workspaceHistory.navigate(target,context))relatedTrail.value=trail.slice(0,-1);
}

const dirty=computed(()=>!!working.value&&JSON.stringify(working.value)!==original.value);
function openConfig(c:Configuration){configRevision.value=revision.value;working.value=clone(c);original.value=JSON.stringify(c);detailTab.value='components';page.value='Configurations';}
function newConfig(){const c:Configuration={id:uid(),name:'Untitled configuration',description:'',systemId:'',status:'Draft',updatedAt:new Date().toISOString(),placements:[],storage:{raid:'none',bootMirror:false},notes:''};openConfig(c);original.value='';}
function duplicate(c:Configuration){const copy=clone(c);delete copy.revision;delete copy.approvalSnapshot;delete copy.approvalHistory;copy.id=uid();copy.name=`${c.name} · copy`;copy.status='Draft';copy.updatedAt=new Date().toISOString();openConfig(copy);original.value='';}
async function saveConfig(event?:PromiseLike<{valid:boolean}>){if(!working.value||busy.value)return;if(!await validateRootForm(configurationForm.value,event)||busy.value||!working.value)return;if(working.value.status==='Approved'&&report.value?.findings.some(f=>f.severity==='error'))return toast('Resolve compatibility conflicts before marking this configuration Approved.');working.value.updatedAt=new Date().toISOString();if(await saveRecord('configurations',working.value,configRevision.value)){working.value=clone(db.value.configurations.find(c=>c.id===working.value?.id)!);original.value=JSON.stringify(working.value);configRevision.value=revision.value;toast('Configuration saved.');}}
const pcSettingsConfiguration=computed(()=>{const pc=pcDraft.value;if(!pc?.buildSettings)return null;return {...installedConfiguration(pc,db.value),storage:pc.buildSettings.storage,portMappings:pc.buildSettings.portMappings,software:pc.software};});
const report=computed(()=>working.value?checkConfiguration(working.value,db.value):null);
const stockAvailability=computed(()=>working.value?stockReadiness(working.value,db.value):[]);
const reports=computed(()=>Object.fromEntries(db.value.configurations.map(c=>[c.id,checkConfiguration(c,db.value)])));
const configs=computed(()=>db.value.configurations.filter(c=>(c.name+' '+c.description+' '+systemName(c.systemId)).toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='All configurations'||(filter.value==='Conflicts'?reports.value[c.id]?.status==='Conflicts':c.status===filter.value))));
const components=computed(()=>{const query=search.value.trim().toLowerCase();return db.value.components.filter(c=>(categoryFilter.value==='All components'||c.category===categoryFilter.value)&&(!familyFilter.value||familyKey(c)===familyFilter.value)&&(!duplicateModelsOnly.value||duplicateModels.value.has(c.id))&&([c.name,c.manufacturer,c.model,c.family,c.category,c.id,summary(c)].join(' ').toLowerCase().includes(query)||!!normalizedModel(query)&&normalizedModel(c.model).includes(normalizedModel(query))));});
const componentPage=ref(1);
watch(categoryFilter,()=>componentPage.value=1);
const componentHeaders=[{title:'Component',key:'name',value:(component:Component)=>`${component.name} ${component.manufacturer}`},{title:'Category',key:'category'},{title:'Specification snapshot',key:'specification',sortable:false},{title:'Verification',key:'verified'},{title:'Actions',key:'actions',sortable:false}];
const systems=computed(()=>filterEquipmentSystems(db.value,search.value,equipmentLocationFilter.value,equipmentDescendants.value));
const equipmentGroups=computed(()=>groupEquipmentSystems(systems.value,db.value,equipmentGrouped.value));
const pcs=computed(()=>db.value.pcs.filter(p=>(p.name+' '+p.serial+' '+p.location).toLowerCase().includes(search.value.toLowerCase())));
const conflictCount=computed(()=>Object.values(reports.value).filter(r=>r.status==='Conflicts').length);
const availableParts=computed(()=>db.value.components.filter(c=>c.category===addCategory.value));
const linkedSystem=computed(()=>{const version=working.value&&resolveRequirementVersion(working.value,db.value);return version?{id:working.value!.requirementSetId||'',name:version.name,description:version.description,location:'',connections:version.connections}:db.value.systems.find(s=>s.id===working.value?.systemId);});
const selectedDrives=computed(()=>working.value?.placements.filter(p=>part(p.componentId)?.category==='Drive'&&!componentCapabilities(part(p.componentId)!).optical)||[]);
const selectedCards=computed(()=>working.value?.placements.filter(p=>!!part(p.componentId)&&componentCapabilities(part(p.componentId)!).slotCard)||[]);
const slots=computed(()=>part(working.value?.placements.find(p=>part(p.componentId)?.category==='Motherboard')?.componentId||'')?.specs.slots||[]);
function part(id:string){return db.value.components.find(c=>c.id===id);}
function systemName(id:string){return db.value.systems.find(s=>s.id===id)?.name||'No equipment linked';}
function configName(id:string){return db.value.configurations.find(c=>c.id===id)?.name||'Unassigned';}
function errors(id:string){return reports.value[id]?.findings.filter(f=>f.severity==='error').length||0;}
function quantity(c:Configuration){return c.placements.reduce((n,p)=>n+p.quantity,0);}
function capacity(n:number|null|undefined){if(n==null||!Number.isFinite(n))return 'Unknown';return n>=1000?`${+(n/1000).toFixed(2)} TB`:`${n} GB`;}
function knownCapacity(cfg:Configuration,role:'boot'|'data',value:number,group?:string){return cfg.placements.some(p=>p.role===role&&(group===undefined||(p.group||'')===group)&&part(p.componentId)?.category==='Drive'&&!componentCapabilities(part(p.componentId)!).optical&&(part(p.componentId)?.specs.capacityGb??0)<=0)?null:value;}
function summary(c:Component){const s=c.specs;switch(c.category){case 'Chassis':return `${s.supportedForms?.join(' / ')||'Form unknown'} · ${s.hotSwapBays??'?'} hot-swap bays`;case 'Motherboard':return `${s.socket||'?'} · ${s.formFactor||'?'} · ${s.slots?.length??'?'} expansion slots`;case 'CPU':return `${s.socket||'Socket unknown'} · ${s.coreCount??'?'} cores / ${s.threadCount??'?'} threads · ${s.powerW??'?'} W`;case 'Memory':return `${s.capacityGb??'?'} GB · ${s.memoryType||'Type unknown'}`;case 'Drive':if(componentCapabilities(c).optical)return `Optical drive · ${s.driveInterface||'?'} · ${s.driveSize||'5.25'}`;return `${s.storageMedium||'Medium unknown'} · ${capacity(s.capacityGb)} · ${s.driveInterface||'?'} · ${s.driveSize||'?'}`;case 'Bay accessory':return `${s.bayUnits??1} × ${s.baySize||'?'} inch bay · ${s.powerW??'?'} W`;case 'Storage adapter':if(!componentCapabilities(c).slotCard)return `${storageAdapterKind(c)==='mount-adapter'?'Mounting adapter':'Drive cage'} · ${s.bayUnits??1} × ${s.baySize||'?'} inch bay · ${s.driveTargets?.length??'?'} drive positions`;return `${storageAdapterKind(c)==='pcie-sled'?'NVMe sled':'Controller'} · ${s.slotBus||'?'} · ${s.sataPorts??s.sledDrives??'?'} ports / positions`;case 'PSU':return `${s.capacityW??'?'} W · ${s.sataPowerConnectors?.length??s.sataPower??'?'} SATA plugs`;case 'Cable':return `${s.connectorA||'?'} → ${s.connectorB||'?'} · ${s.cableProtocol||'Protocol unknown'} · ${s.cableChannels??'?'} channels · ${s.lengthMm??'?'} mm`;case 'Consumable':return `${s.consumableKind||'Consumable'} · ${s.stockUnit||'piece'}${s.thicknessMm?' · '+s.thicknessMm+' mm':''}`;case 'Fan':return `${s.lengthMm??'?'} mm · ${s.coolingDevices?.map(d=>d.control||'Control unknown').join(', ')||'Cooling details unknown'}`;case 'Cooler':return `${s.heightMm??'?'} mm · ${s.supportsSockets?.join(', ')||'Socket unknown'}`;default:return `${s.slotBus||'?'} x${s.slotWidth||'?'} · ${s.requiredLanes||'?'} lanes · ${s.lengthMm??'?'} mm`;}}
function addComponent(){if(!working.value||!addPart.value)return;working.value.placements.push({id:uid(),componentId:addPart.value,quantity:addQty.value,slotId:'',role:part(addPart.value)?.category==='Drive'&&!componentCapabilities(part(addPart.value)!).optical?'data':'general',mount:'auto',group:''});addPart.value='';addQty.value=1;}
function splitPlacement(p:Placement){if(!working.value)return;try{working.value=splitConfigurationPlacement(working.value,p.id,uid);}catch(e){toast(e instanceof Error?e.message:String(e));}}

function removePlacement(id:string){if(working.value)working.value.placements=working.value.placements.filter(p=>p.id!==id);}
const componentDataEditor=ref<InstanceType<typeof ComponentDataEditor>|null>(null);
function editComponent(c?:Component){editorRevision.value=revision.value;componentDraft.value=c?clone(c):{id:uid(),name:'',category:'Scientific card',manufacturer:'',specs:{},source:'',verified:false};editorOriginal.value=JSON.stringify(componentDraft.value);}
async function saveComponent(event?:PromiseLike<{valid:boolean}>){if(!componentDraft.value||busy.value)return;if(!await componentDataEditor.value?.validate())return;if(!await validateRootForm(componentForm.value,event)||busy.value||!componentDraft.value)return;if(await saveRecord('components',componentDraft.value)){componentDraft.value=null;toast('Component saved.');}}
function editSystem(s?:System){editorRevision.value=revision.value;systemDraft.value=s?clone(s):{id:uid(),name:'',location:'',description:'',connections:[]};editorOriginal.value=JSON.stringify(systemDraft.value);}
async function saveSystem(event?:PromiseLike<{valid:boolean}>){if(busy.value)return;if(!await validateRootForm(systemForm.value,event)||busy.value||!systemDraft.value)return;if(systemDraft.value&&await saveRecord('systems',systemDraft.value)){systemDraft.value=null;toast('Equipment system saved.');}}
function editPC(p?:InventoryPC){editorRevision.value=revision.value;pcDraft.value=p?clone(p):{id:uid(),name:'',serial:'',location:'',configurationId:'',notes:'',buildSettings:null};pcDraft.value.software??=clone(pcDraft.value.buildSettings?.software||{});if(pcDraft.value.buildSettings){const settings=installedConfiguration(pcDraft.value,db.value);pcDraft.value.buildSettings.portMappings=settings.portMappings||[];if(settings.storage.groups)pcDraft.value.buildSettings.storage.groups=settings.storage.groups;}editorOriginal.value=JSON.stringify(pcDraft.value);}
function captureTemplateSettings(copySoftware=true){const cfg=db.value.configurations.find(c=>c.id===pcDraft.value?.configurationId);if(pcDraft.value&&cfg){if(copySoftware||!pcDraft.value.software||!Object.keys(pcDraft.value.software).length)pcDraft.value.software=clone(cfg.software||{});pcDraft.value.buildSettings={systemId:cfg.systemId,storage:clone(cfg.storage),notes:cfg.notes,software:clone(cfg.software||{}),portMappings:clone(cfg.portMappings||[]),requirementSetId:cfg.requirementSetId,requirementRevision:cfg.requirementRevision,requirementSnapshot:clone(cfg.requirementSnapshot)};if(db.value.inventory.some(s=>s.allocations.some(a=>a.pcId===pcDraft.value?.id&&a.state==='installed')))pcDraft.value.buildSettings.portMappings=installedConfiguration(pcDraft.value,db.value).portMappings||[];}}
async function savePC(event?:PromiseLike<{valid:boolean}>){if(busy.value)return;if(!await validateRootForm(pcForm.value,event)||busy.value||!pcDraft.value)return;if(pcDraft.value&&!db.value.pcs.some(p=>p.id===pcDraft.value?.id)&&!pcDraft.value.buildSettings&&!pcDraft.value.hardwareSurvey)captureTemplateSettings(false);if(pcDraft.value&&await saveRecord('pcs',pcDraft.value)){pcDraft.value=null;toast('PC saved.');}}
async function deleteRecord(){if(!confirmDelete.value)return;busy.value=true;try{await api(`/api/${confirmDelete.value.collection}/${confirmDelete.value.id}`,{method:'DELETE',headers:{'If-Match':revision.value}});await load();if(working.value?.id===confirmDelete.value.id)working.value=null;confirmDelete.value=null;toast('Record deleted.');}catch(e){toast(String(e));}finally{busy.value=false;}}


const editorDirty=computed(()=>{const d=componentDraft.value||systemDraft.value||pcDraft.value;return !!d&&(JSON.stringify(d)!==editorOriginal.value||!!componentDataEditor.value?.hasPendingChanges());});
function closeEditor(kind:'component'|'system'|'pc'){if(busy.value)return;if(editorDirty.value&&!window.confirm('Discard unsaved changes?'))return;if(kind==='component')componentDraft.value=null;else if(kind==='system')systemDraft.value=null;else pcDraft.value=null;}
async function refreshWorkspace(){if(!confirmWorkspaceDiscard())return;working.value=null;componentDraft.value=null;systemDraft.value=null;pcDraft.value=null;refreshEpoch.value++;await load();}

function hasPendingChanges(){return !!(identifyEditor.value?.hasUnsavedChanges()||mergeEditor.value?.hasUnsavedChanges()||transitionsWorkspace.value?.hasUnsavedChanges()||recordTable2.value?.hasUnsavedChanges()||recordTable3.value?.hasUnsavedChanges()||settingsWorkspace.value?.hasUnsavedChanges()||dirty.value||editorDirty.value||catalogMaintenance.value?.hasUnsavedChanges()||inventoryWorkspace.value?.hasUnsavedChanges()||installationsWorkspace.value?.hasUnsavedChanges());}
function beforeUnload(e:BeforeUnloadEvent){if(busy.value||importing.value||hasPendingChanges()){e.preventDefault();e.returnValue='';}}
const removeNativeCloseDecision=installNativeCloseDecision(()=>{
 if(busy.value||importing.value)return false;
 return !hasPendingChanges()||window.confirm('Discard unsaved changes and close PC Workbench?');
});
onBeforeUnmount(removeNativeCloseDecision);
if(import.meta.hot){const stopDevGuard=installDevUpdateGuard(import.meta.hot,()=>busy.value||importing.value||hasPendingChanges(),()=>toast('Development update paused. Save or discard your changes to load the update.'));onBeforeUnmount(stopDevGuard);import.meta.hot.dispose(stopDevGuard);}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
async function previewRestore(){try{if(!restoreFile.value)return;restoreBackup.value=JSON.parse(await restoreFile.value.text());restorePreview.value=await api('/api/restore/preview',{method:'POST',body:JSON.stringify({backup:restoreBackup.value})});}catch(e){toast(String(e));restorePreview.value=null;}}
async function commitRestore(){if(!restorePreview.value)return;if(!window.confirm('Replace the entire workspace with this backup? A safety backup will be saved first.'))return;busy.value=true;try{const result=await api('/api/restore',{method:'POST',headers:{'If-Match':restorePreview.value.revision},body:JSON.stringify({backup:restoreBackup.value,backupRevision:restorePreview.value.backupRevision})});await load();restorePreview.value=null;restoreFile.value=null;toast(`Workspace restored. Safety backup: ${result.backupFile}`);}catch(e){toast(String(e));}finally{busy.value=false;}}


const requirementChoices=computed(()=>[{title:'No installation requirements linked',value:''},...db.value.requirementsSets.filter(s=>s.versions.length).map(s=>({title:s.name,value:s.id}))]);
function requirementRevisions(id:string){return db.value.requirementsSets.find(s=>s.id===id)?.versions.map(v=>({title:`Revision ${v.revision} · ${v.name}`,value:v.revision}))||[];}
function selectConfigRequirements(){if(!working.value)return;working.value.requirementRevision=db.value.requirementsSets.find(s=>s.id===working.value!.requirementSetId)?.versions.at(-1)?.revision||0;updateConfigRequirements();}
function updateConfigRequirements(){if(!working.value)return;const selected=db.value.requirementsSets.find(s=>s.id===working.value!.requirementSetId)?.versions.find(v=>v.revision===working.value!.requirementRevision);if(selected)working.value.requirementSnapshot=clone(selected);else delete working.value.requirementSnapshot;}
function selectPCRequirements(){if(!pcDraft.value?.buildSettings)return;const settings=pcDraft.value.buildSettings;settings.requirementRevision=db.value.requirementsSets.find(s=>s.id===settings.requirementSetId)?.versions.at(-1)?.revision||0;updatePCRequirements();}
function updatePCRequirements(){if(!pcDraft.value?.buildSettings)return;const settings=pcDraft.value.buildSettings;const version=db.value.requirementsSets.find(s=>s.id===settings.requirementSetId)?.versions.find(v=>v.revision===settings.requirementRevision);if(version)settings.requirementSnapshot=clone(version);else delete settings.requirementSnapshot;}
function selectPCLocation(){if(!pcDraft.value)return;const location=db.value.installationLocations.find(l=>l.id===pcDraft.value!.installationLocationId);if(location&&!pcDraft.value.configurationId)pcDraft.value.configurationId=location.targetConfigurationId;}

onMounted(async()=>{await load();await workspaceHistory.start();const context=(document as Document&{modelContext?:{registerTool:(t:unknown)=>Promise<void>}}).modelContext;if(context){for(const tool of [{name:'list_configurations',description:'Read saved PC configurations and compatibility summaries.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>db.value.configurations.map(c=>({id:c.id,name:c.name,status:reports.value[c.id].status}))},{name:'check_configuration',description:'Read compatibility findings for a saved configuration.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:true},execute:(input:{id:string})=>{const c=db.value.configurations.find(c=>c.id===input.id);if(!c)throw Error('Unknown configuration');return checkConfiguration(c,db.value);}}])try{await context.registerTool(tool);}catch{ /* Optional browser API. */ }}});

const recordTable2=ref<InstanceType<typeof RecordTable>|null>(null);
const recordTable3=ref<InstanceType<typeof RecordTable>|null>(null);
function breadcrumbLink(title:string,target:WorkspaceRoute){return {title,href:encodeWorkspaceRoute(target),onClick:(event:Event)=>{const click=event as MouseEvent;if(click.metaKey||click.ctrlKey||click.shiftKey||click.altKey||click.button>0)return;event.preventDefault();void workspaceHistory.navigate(target);}};}
const breadcrumbItems=computed(()=>{
 const route=readRoute(),root=workspaceRoute(route.page),subpage=!!route.id||!!route.editor||route.view!==root.view;
 const items:Array<{title:string;disabled?:boolean;href?:string;onClick?:(event:Event)=>void}>=[{title:'Workspace',disabled:true},subpage?breadcrumbLink(route.page,root):{title:route.page,disabled:true}];
 const viewNames:Record<string,string>={components:'Components',gaps:'Missing data',queue:'Enrichment queue',connections:'Connections',storage:'Storage plan',checks:'Compatibility',parts:'Parts & reservations',readiness:'Build readiness',report:'Installed compatibility',history:'History',allocations:'Allocations',locations:'Installation locations',requirements:'Requirements sets',operations:'Location operations',distribution:'Distribution review'};
 if(route.id){const title=route.page==='Configurations'?working.value?.name:route.page==='PC inventory'?db.value.pcs.find(p=>p.id===route.id)?.name:route.page==='Component inventory'?part(db.value.inventory.find(stock=>stock.id===route.id)?.componentId||'')?.name:route.page==='Installations'?locationPath(route.id,db.value):'Transition plan';const recordRoute={...route,editor:'' as const,editorId:''};items.push(route.editor?breadcrumbLink(title||route.id,recordRoute):{title:title||route.id,disabled:true});}
 if(route.view&&route.view!==root.view)items.push({title:viewNames[route.view]||route.view,disabled:true});
 if(route.editor)items.push({title:route.editorId==='new'?`New ${route.editor}`:route.editor==='component'?db.value.components.find(c=>c.id===route.editorId)?.name||'Component':route.editor==='system'?db.value.systems.find(system=>system.id===route.editorId)?.name||'Equipment system':db.value.pcs.find(pc=>pc.id===route.editorId)?.name||'PC',disabled:true});
 return items;
});
const workspaceHistory=createWorkspaceHistory({read:readRoute,capture:captureView,apply:applyRoute,canLeave:canLeaveRoute});
watch(()=>JSON.stringify({route:readRoute(),context:captureView()}),()=>workspaceHistory.sync(),{flush:'post'});
onBeforeUnmount(()=>workspaceHistory.stop());
</script>

<template>
 <v-app><a class="skip-link" href="#main-content">Skip to main content</a>
  <v-navigation-drawer id="workspace-navigation" v-model="navigationOpen" class="workspace-drawer" :temporary="smAndDown" :mobile="smAndDown" disable-resize-watcher :order="smAndDown?1:0" :width="smAndDown?'100%':304" aria-label="Application navigation" @keydown.esc.stop.prevent="closeMobileNav">
   <a class="brand" href="#" @click.prevent="navigate('Configurations')"><span class="brand-mark">b<span>.</span></span><span>bench<span class="brand-period">.</span></span></a>
   <nav aria-label="Main navigation"><v-list nav tag="div" role="presentation" :tabindex="-1"><v-list-item v-for="item in navigation" :key="item.name" tag="button" role="button" :tabindex="0" class="workspace-nav-item" :active="page===item.name" :aria-label="item.name" :aria-current="page===item.name?'page':undefined" :prepend-icon="item.icon" :title="item.name" @click="navigate(item.name)"><template v-if="item.name==='Configurations'" #append><v-chip size="small" variant="tonal" :text="String(db.configurations.length)" /></template></v-list-item></v-list></nav>
   <template #append><v-list nav tag="div" role="presentation" :tabindex="-1"><v-list-item tag="button" role="button" :tabindex="0" class="workspace-nav-item" :active="page==='Data & imports'" :aria-current="page==='Data & imports'?'page':undefined" :prepend-icon="mdiDatabaseOutline" title="Data & imports" aria-label="Data & imports" @click="navigate('Data & imports')" /><v-list-item tag="button" role="button" :tabindex="0" class="workspace-nav-item" :active="page==='Settings'" :aria-current="page==='Settings'?'page':undefined" :prepend-icon="mdiCogOutline" title="Settings" aria-label="Settings" @click="navigate('Settings')" /></v-list><div class="workspace-storage"><span class="status-dot" /> SQLite storage</div></template>
  </v-navigation-drawer>
  <v-app-bar class="workspace-app-bar" :order="smAndDown?0:1" :height="smAndDown?128:80" elevation="0" border="b">
   <div class="workspace-bar-path">
   <v-btn id="mobile-nav-toggle" :icon="mdiMenu" variant="text" aria-label="Toggle navigation" aria-controls="workspace-navigation" :aria-expanded="navigationOpen" @click="navigationOpen=!navigationOpen" />
   <nav aria-label="Breadcrumb"><v-breadcrumbs :items="breadcrumbItems" /></nav>
   </div>
   <div class="workspace-app-actions"><label class="appearance-control"><span class="sr-only">Appearance</span><select :disabled="!!appearanceDraft||!settingsReady" :value="themePreference" aria-label="Appearance" @change="changeAppearance"><option value="system">System theme</option><option value="light">Light theme</option><option value="dark">Dark theme</option></select></label><v-btn variant="text" :icon="mdiRefresh" aria-label="Reload workspace" @click="refreshWorkspace" /></div>
  </v-app-bar>
  <v-main id="main-content" class="workspace-main" tabindex="-1" aria-label="Workspace content">
   <div v-if="loading" class="loading-state"><v-progress-circular indeterminate color="primary" /><p>Opening your workbench…</p></div>
   <div v-else-if="failure" class="page-content"><v-alert type="error" role="alert" title="Cannot connect to the local server">{{failure}}<br>Start the app with pnpm dev or pnpm start.</v-alert><v-btn class="mt-4" @click="load">Retry</v-btn></div>
   <div v-else :key="refreshEpoch" class="page-content"><v-alert v-if="recoveryRequired" type="error" role="alert" class="mb-6" title="Workspace recovery required">A disk operation could not finish safely. Edits are blocked. Stop and restart the local server to process recovery before continuing.</v-alert>
    <div v-if="relatedTrail.length" class="detail-back"><button type="button" @click="backToRelated"><v-icon :icon="mdiArrowLeft" aria-hidden="true" size="16" />Back to {{relatedTrail[relatedTrail.length-1].page}}</button></div>
    <SettingsWorkspace v-if="page==='Settings'" ref="settingsWorkspace" />
    <TransitionsWorkspace v-else-if="page==='Configuration transitions'" ref="transitionsWorkspace" :db="db" :revision="revision" @edit-component="editComponent" @edit-pc="editPC" @reload="load" @open-installations="navigate('Installations')" @notify="toast" @open-related="openRelated" />
    <v-form v-else-if="working" ref="configurationForm" :disabled="busy" validate-on="blur" @submit.prevent="saveConfig">
     <div class="detail-back"><button type="button" @click="navigate('Configurations')"><v-icon aria-hidden="true" :icon="mdiArrowLeft" size="16" />All configurations</button><span>{{dirty?'Unsaved changes':'Saved'}}</span></div>
     <div class="page-heading"><div><div class="eyebrow">CONFIGURATION BUILDER</div><h1>{{working.name}}</h1><p>Build the PC around the system it needs to run.</p></div><div class="heading-actions"><v-btn variant="outlined" :prepend-icon="mdiContentCopy" @click="duplicate(working)">Duplicate</v-btn><v-btn color="primary" :prepend-icon="mdiCheck" :loading="busy" :disabled="busy||!working.name.trim()" type="submit">Save configuration</v-btn></div></div>
     <div class="related-links"><v-btn v-for="pc in db.pcs.filter(pc=>pc.configurationId===working?.id)" :key="pc.id" variant="text" @click="openRelated({kind:'pc',id:pc.id})">Open PC: {{pc.name}}</v-btn></div><section class="builder-meta panel" :inert="busy"><v-select v-model="working.requirementSetId" label="Installation requirements set" :items="requirementChoices" @update:model-value="selectConfigRequirements" /><v-select v-if="working.requirementSetId" v-model="working.requirementRevision" label="Pinned requirements revision" :items="requirementRevisions(working.requirementSetId)" @update:model-value="updateConfigRequirements" /><v-text-field v-model="working.name" label="Configuration name" /><v-select v-model="working.systemId" label="Equipment system" :items="[{title:'No equipment linked',value:''},...db.systems.map(s=>({title:s.name,value:s.id}))]" /><v-select v-model="working.status" label="Workflow status" :items="['Draft','In review','Approved']" /><v-text-field v-model="working.description" label="Description" class="meta-description" /></section>
     <div class="builder-grid" :inert="busy"><div class="builder-main">
      <v-tabs v-model="detailTab" color="primary" class="content-tabs"><v-tab id="configuration-tab-components" aria-controls="configuration-panel-components" value="components">Components <span class="tab-count">{{working.placements.length}}</span></v-tab><v-tab id="configuration-tab-connections" aria-controls="configuration-panel-connections" value="connections">Connections</v-tab><v-tab id="configuration-tab-storage" aria-controls="configuration-panel-storage" value="storage">Storage plan</v-tab><v-tab id="configuration-tab-checks" aria-controls="configuration-panel-checks" value="checks">Compatibility</v-tab></v-tabs>
      <section id="configuration-panel-components" role="tabpanel" aria-labelledby="configuration-tab-components" v-show="detailTab==='components'" class="panel builder-section"><div class="section-head"><div><h2>Bill of materials</h2><p>Quantities use each catalog model’s stock unit: modules, drives, cable assemblies or consumable pieces.</p></div><span class="neutral-badge">{{quantity(working)}} parts</span></div>
       <div class="add-component"><v-select v-model="addCategory" label="Category" :items="categories" @update:model-value="addPart=''" /><v-select v-model="addPart" label="Choose a component" :items="availableParts.map(c=>({title:c.model?componentIdentityLabel(c):c.name,value:c.id}))" /><v-text-field v-model.number="addQty" label="Qty" type="number" min="1" max="32" /><v-btn color="primary" :icon="mdiPlus" aria-label="Add component" :disabled="!addPart||!Number.isInteger(addQty)||addQty<1||addQty>32" @click="addComponent" /></div>
       <div v-if="!working.placements.length" class="empty-state"><v-icon aria-hidden="true" :icon="mdiCubeOutline" size="34" /><h3>Your build starts here</h3><p>Add a chassis, motherboard, CPU and components.</p></div>
       <div v-for="p in working.placements" :key="p.id" class="bom-row"><span class="part-icon"><v-icon aria-hidden="true" :icon="part(p.componentId)?.category==='Drive'?mdiHarddisk:mdiMemory" size="22" /></span><div class="bom-name"><small>{{part(p.componentId)?.category}}</small><strong>{{part(p.componentId)?.name||'Missing component'}}</strong><span>{{part(p.componentId)?summary(part(p.componentId)!):p.componentId}}</span></div><v-text-field v-model.number="p.quantity" label="Qty" type="number" min="1" max="32" class="qty-input" :rules="[quantityRule]" /><v-btn variant="text" :icon="mdiClose" size="small" aria-label="Remove component from build" @click="removePlacement(p.id)" /></div>
       <div v-if="selectedCards.length" class="slot-section"><h3>Expansion slot assignments</h3><p>Auto allocation checks bus, lanes and adjacent brackets. Choose a slot to reserve it.</p><div v-for="p in selectedCards" :key="p.id" class="slot-assignment"><span>{{part(p.componentId)?.name}}<v-btn v-if="p.quantity>1" size="x-small" variant="text" @click="splitPlacement(p)">Split into individual cards</v-btn></span><v-select v-model="p.slotId" :items="[{title:'Auto-assign',value:''},...slots.map(s=>({title:`${s.id} · ${slotSummary(s)}`,value:s.id}))]" label="Reserved slot" /><small><span v-for="i in p.quantity" :key="i" class="d-block">Unit {{i}}: {{report?.slotAssignments[`${p.id}:${i-1}`]||'Unallocated'}}</span></small></div></div>
      </section>
      <section id="configuration-panel-connections" role="tabpanel" aria-labelledby="configuration-tab-connections" v-show="detailTab==='connections'" class="panel builder-section"><div class="section-head"><div><h2>Equipment connections</h2><p>{{linkedSystem?.description||'Choose an equipment system above to check required ports.'}}</p></div><v-btn v-if="linkedSystem && !working.requirementSetId" variant="outlined" size="small" @click="editSystem(linkedSystem)">Edit system</v-btn></div><template v-if="linkedSystem"><div class="port-summary"><div v-for="(total,i) in connectionPortTotals(linkedSystem.connections)" :key="i"><strong>{{total.quantity}}</strong><span>{{total.label}} required</span></div></div><div v-for="connection in linkedSystem.connections" :key="connection.id" class="connection-row"><v-icon aria-hidden="true" :icon="mdiLan" /><div><strong>{{connection.name}}</strong><p>{{connection.notes||'No additional requirements recorded.'}}</p><p v-for="requirement in connection.requirements" :key="requirement.id" class="form-hint">{{requirement.quantity}} {{portLabel(requirement)}}<template v-if="requirement.protocol"> · {{requirement.protocol}}</template><template v-if="requirement.connector"> · {{requirement.connector}}</template><template v-if="requirement.pinout"> · {{requirement.pinout}}</template></p></div><span>{{connectionSummary(connection)}}</span></div><div class="info-callout"><v-icon aria-hidden="true" :icon="mdiInformationOutline" size="19" />Counts cover dedicated physical connections. Verify connectors, protocol, pinout, bandwidth, power, isolation and required cables or converters for each device.</div></template><CoolingConnectionsEditor :configuration="working" :db="db" /></section>
      <section id="configuration-panel-storage" role="tabpanel" aria-labelledby="configuration-tab-storage" v-show="detailTab==='storage'" class="panel builder-section"><div class="section-head"><div><h2>Storage & serviceability</h2><p>Separate boot and data, then plan access and redundancy.</p></div></div><div class="storage-options"><v-select v-model="working.storage.raid" label="Data redundancy" :items="[{title:'Independent drives',value:'none'},{title:'Mirror · 2 drives',value:'mirror'},{title:'RAID 5 · 3+ drives',value:'raid5'},{title:'RAID 6 · 4+ drives',value:'raid6'},{title:'RAID 10 · even, 4+ drives',value:'raid10'}]" /><v-switch v-model="working.storage.bootMirror" label="Mirror boot drive pair" color="primary" hide-details /></div><div class="storage-capacities"><div><small>BOOT CAPACITY</small><strong>{{capacity(knownCapacity(working,'boot',report?.bootGb||0))}}</strong></div><div><small>USABLE DATA CAPACITY</small><strong>{{capacity(knownCapacity(working,'data',report?.usableDataGb||0))}}</strong></div></div><div v-if="!selectedDrives.length" class="empty-state"><h3>No drives selected</h3><p>Add drives in the Components tab to begin your plan.</p></div><div v-for="p in selectedDrives" :key="p.id" class="drive-row"><div><strong>{{part(p.componentId)?.name}}</strong><small>{{p.quantity}} × {{capacity(part(p.componentId)?.specs.capacityGb)}}</small><v-btn v-if="p.quantity>1" size="x-small" variant="text" @click="splitPlacement(p)">Split into individual drives</v-btn></div><v-select v-model="p.role" label="Drive role" :items="['boot','data','general']" /><v-select v-model="p.mount" label="Mount / access" :items="[{title:'Automatic / onboard',value:'auto'},{title:'Internal bay',value:'internal'},{title:'Front hot-swap bay',value:'front-hot-swap'},{title:'Rear PCIe NVMe sled',value:'rear-sled'}]" /></div><div class="info-callout"><v-icon aria-hidden="true" :icon="mdiInformationOutline" size="19" />Capacity uses decimal GB/TB before filesystem overhead. Assign data drives to named redundancy groups below. Rear NVMe sleds require a selected adapter and may require bifurcation; hot-swap is vendor dependent.</div></section>
      <section id="configuration-panel-checks" role="tabpanel" aria-labelledby="configuration-tab-checks" v-show="detailTab==='checks'" class="panel builder-section"><div class="section-head"><div><h2>Compatibility report</h2><p>Checks update as you edit. Resolve conflicts and verify the review items.</p></div></div><div v-for="(f,i) in report?.findings" :key="i" :class="['finding',f.severity]"><v-icon aria-hidden="true" :icon="f.severity==='pass'?mdiCheckCircleOutline:mdiAlertCircleOutline" size="20" /><div><strong>{{f.title}}</strong><p>{{f.detail}}</p></div><span>{{f.severity==='error'?'Conflict':f.severity==='warning'?'Review':'Pass'}}</span></div></section>
      <section v-if="report?.storageGroups?.length" class="panel build-notes"><h3>Array capacities</h3><v-table v-table-scroll="'Array capacities'" data-workspace-table="Array capacities"><caption class="sr-only">Array capacities</caption><thead><tr><th scope="col">ARRAY</th><th scope="col">LAYOUT</th><th scope="col">DRIVES</th><th scope="col">USABLE</th></tr></thead><tbody><tr v-for="g in report.storageGroups" :key="g.id"><td>{{g.name}}</td><td>{{g.raid}}</td><td>{{g.driveCount}}</td><td>{{capacity(knownCapacity(working,'data',g.usableGb,working.storage.groups?.some(group=>group.id===g.id)?g.id:''))}}</td></tr></tbody></v-table></section><section class="panel build-notes stock-readiness"><div class="section-head"><div><h3>Stock readiness for this build</h3><p>Free, serviceable units. Reservations for other PCs are excluded.</p></div><v-btn variant="text" size="small" @click="navigate('Component inventory')">Manage stock</v-btn></div><RecordTable v-if="stockAvailability.length" v-table-scroll="'Configuration stock readiness'" data-workspace-table="Configuration stock readiness" label="Configuration stock readiness" :headers="[{title:'Component',key:'c0',sortable:true},{title:'Required',key:'c1',sortable:true},{title:'Available',key:'c2',sortable:true},{title:'Shortage',key:'c3',sortable:true}]" :items="(stockAvailability).map((row)=>({id:(row.componentId),record:(row),c0:(part(row.componentId)?.name),c1:(row.required),c2:(row.available),c3:(row.shortage)}))"><template #c0="{item:{record:row}}"><div>{{part(row.componentId)?.name}}</div></template><template #c1="{item:{record:row}}"><div>{{row.required}}</div></template><template #c2="{item:{record:row}}"><div>{{row.available}}</div></template><template #c3="{item:{record:row}}"><div :class="{'text-error':row.shortage>0}">{{row.shortage}}</div></template></RecordTable><p v-else class="form-hint">Add components to see physical stock availability.</p></section>
      <section v-if="working.approvalHistory?.length" class="panel build-notes"><h3>Approved versions</h3><details v-for="version in [...working.approvalHistory].reverse()" :key="version.revision" class="my-4"><summary>Version {{version.revision}} · {{new Date(version.at).toLocaleString()}} · {{version.configuration.name}}</summary><p class="form-hint">Captured specifications and equipment requirements are preserved with this version.</p><pre class="snapshot-json" tabindex="0" role="region" aria-label="Approved configuration revision details">{{JSON.stringify(version,null,2)}}</pre></details></section><section class="panel build-notes"><EngineeringEditor :configuration="working" :db="db" /><BayEditor :configuration="working" :db="db" /><StorageConnectionsEditor :configuration="working" :db="db" /><h3>Build notes</h3><v-textarea v-model="working.notes" label="Installation, drivers, verification and commissioning notes" rows="3" /></section>
     </div><aside class="build-summary" aria-label="Configuration health and capacity"><section class="panel"><div class="summary-title"><v-icon aria-hidden="true" :icon="mdiCheckCircleOutline" size="20" /><h3>Build health</h3></div><v-chip :color="report?.status==='Conflicts'?'error':report?.status==='Compatible'?'success':'warning'" variant="tonal">{{report?.status}}</v-chip><p>{{report?.findings.filter(f=>f.severity==='error').length}} conflicts · {{report?.findings.filter(f=>f.severity==='warning').length}} review items</p><v-btn variant="text" color="primary" :append-icon="mdiArrowRight" class="report-link" @click="detailTab='checks'">View full report</v-btn><v-divider class="my-4" /><h4>Capacity overview</h4><div v-for="r in report?.resources" :key="r.name" class="resource"><div><span>{{r.name}}</span><strong :class="{over:r.used>r.available}">{{r.used}} / {{r.available}}{{r.unit}}</strong></div><v-progress-linear :aria-label="`${r.name} capacity used`" :model-value="r.available?Math.min(100,r.used/r.available*100):r.used?100:0" :color="r.used>r.available?'error':'primary'" height="4" rounded /></div><div class="summary-foot">Planning checks are based on catalog specifications. Review manufacturer documentation before purchasing or installing.</div></section><v-btn variant="text" color="error" :prepend-icon="mdiTrashCanOutline" @click="confirmDelete={collection:'configurations',id:working.id,name:working.name}">Delete configuration</v-btn></aside></div>
    </v-form>

    <template v-else-if="page==='Configurations'">
     <div class="page-heading"><div><div class="eyebrow">YOUR HARDWARE, IN HARMONY</div><h1>Configurations</h1><p>A home for every build. A clear path from parts to purpose.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="newConfig">New configuration</v-btn></div>
     <div class="overview-grid"><div class="stat-card"><div><span>Total configurations</span><v-icon aria-hidden="true" :icon="mdiDesktopTowerMonitor" size="19" /></div><strong>{{db.configurations.length.toString().padStart(2,'0')}}</strong><small>Designed for your equipment</small></div><div class="stat-card"><div><span>Components in catalog</span><v-icon aria-hidden="true" :icon="mdiMemory" size="19" /></div><strong>{{db.components.length.toString().padStart(2,'0')}}</strong><small>From chassis to scientific cards</small></div><div class="stat-card"><div><span>Connected systems</span><v-icon aria-hidden="true" :icon="mdiLan" size="19" /></div><strong>{{db.systems.length.toString().padStart(2,'0')}}</strong><small>Equipment requirements mapped</small></div><div class="stat-card attention"><div><span>Needs attention</span><v-icon aria-hidden="true" :icon="mdiAlertCircleOutline" size="19" /></div><strong>{{conflictCount.toString().padStart(2,'0')}}</strong><small>Builds with compatibility conflicts</small></div></div>
     <div class="list-toolbar"><v-btn-toggle v-model="filter" mandatory class="configuration-filters" role="group" aria-label="Filter configurations" variant="outlined"><v-btn value="All configurations" :aria-pressed="filter==='All configurations'">All configurations <span class="filter-count">{{db.configurations.length}}</span></v-btn><v-btn value="Draft" :aria-pressed="filter==='Draft'">Drafts</v-btn><v-btn value="In review" :aria-pressed="filter==='In review'">In review</v-btn><v-btn value="Conflicts" :aria-pressed="filter==='Conflicts'">Conflicts</v-btn></v-btn-toggle><v-text-field :model-value="search" @update:model-value="v=>search=String(v??'')" clearable placeholder="Search configurations…" :prepend-inner-icon="mdiMagnify" aria-label="Search configurations" hide-details class="search-input" /></div>
     <div class="config-grid"><article v-for="c in configs" :key="c.id" class="config-card"><div class="config-card-top"><span class="config-icon"><v-icon aria-hidden="true" :icon="mdiDesktopTowerMonitor" size="24" /></span><span :class="['workflow-badge',c.status==='In review'?'in-review':c.status==='Approved'?'approved':'']"><span />{{c.status}}</span></div><button type="button" class="card-title" @click="openConfig(c)">{{c.name}}<v-icon aria-hidden="true" :icon="mdiArrowTopRight" size="19" /></button><p class="card-description">{{c.description}}</p><div class="system-label"><v-icon aria-hidden="true" :icon="mdiLan" size="16" />{{systemName(c.systemId)}}</div><div class="card-facts"><div><small>COMPONENTS</small><strong>{{quantity(c)}} <span>parts</span></strong></div><div><small>DATA STORAGE</small><strong>{{capacity(knownCapacity(c,'data',reports[c.id]?.usableDataGb||0))}}</strong></div></div><div :class="['card-health',errors(c.id)?'has-conflicts':'']"><v-icon aria-hidden="true" :icon="errors(c.id)?mdiAlertCircleOutline:mdiCheckCircleOutline" size="17" /><span>{{errors(c.id)?`${errors(c.id)} compatibility conflicts`:'No conflicts · review required'}}</span></div><div class="card-footer"><span>Updated {{new Date(c.updatedAt).toLocaleDateString('en-US',{month:'short',day:'numeric'})}}</span><button type="button" @click="openConfig(c)">Open build <v-icon aria-hidden="true" :icon="mdiArrowRight" size="16" /></button></div></article><button type="button" class="new-build-card" @click="newConfig"><span><v-icon aria-hidden="true" :icon="mdiPlus" size="26" /></span><h3>Your next configuration</h3><p>Start with a purpose.<br>Find the right parts.</p><strong>Create a new build <v-icon aria-hidden="true" :icon="mdiArrowRight" size="16" /></strong></button></div>
     <div v-if="!configs.length" class="empty-state"><h3>No configurations found</h3><p>Try a different search or create your first build.</p></div>
     <div class="bottom-note"><v-icon aria-hidden="true" :icon="mdiInformationOutline" size="16" />Example workspace included. Verify or replace illustrative specifications before using a build.</div>
    </template>

    <template v-else-if="page==='Component catalog'">
     <div class="page-heading"><div><div class="eyebrow">THE PARTS THAT MAKE IT POSSIBLE</div><h1>Component catalog</h1><p>Browse component models, fill missing specifications, and review enrichment.</p></div><div class="heading-actions"><v-btn variant="outlined" :prepend-icon="mdiDownload" href="/api/export/components">Export CSV</v-btn><v-btn variant="outlined" @click="mergeSources=[]">Merge component types</v-btn><v-btn color="primary" :prepend-icon="mdiPlus" @click="editComponent()">Add component</v-btn></div></div>
     <v-tabs :model-value="catalogView" aria-label="Catalog views" class="content-tabs" @update:model-value="v=>changeCatalogView(String(v))"><v-tab value="components">Components</v-tab><v-tab value="gaps" :aria-label="`Missing data (${catalogMissingCount})`" title="Components with missing core data or awaiting verification; total across catalog filters">Missing data<span class="tab-count">{{catalogMissingCount}}</span></v-tab><v-tab value="queue" :aria-label="`Enrichment queue (${catalogQueueLoaded?catalogQueueJobs.length:catalogQueueError?'unavailable':'loading'})`" :title="catalogQueueError?'Queue refresh unavailable; retrying. Any displayed count is the last known total.':'All queue entries, including failed jobs and retained completed/cancelled history'">Enrichment queue<span class="tab-count">{{catalogQueueLoaded?catalogQueueJobs.length:catalogQueueError?'—':'…'}}</span></v-tab></v-tabs><template v-if="catalogView==='components'"><div class="catalog-toolbar"><v-text-field :model-value="search" @update:model-value="v=>search=String(v??'')" clearable placeholder="Search names, models, families or manufacturers…" :prepend-inner-icon="mdiMagnify" aria-label="Search components" hide-details /><v-select v-model="categoryFilter" :items="['All components',...categories]" label="Category" hide-details /><v-autocomplete v-model="familyFilter" :items="familyChoices" label="Filter family / series" clearable hide-details /><span>{{components.length}} components</span></div><div class="d-flex flex-wrap ga-4 mb-4"><v-checkbox v-model="familyGrouped" label="Group by manufacturer and family" hide-details /><v-checkbox v-model="duplicateModelsOnly" :label="`Possible duplicate models only (${duplicateModels.size})`" hide-details /></div>
     <section class="panel table-panel"><RecordTable :searchable="false" :group-by="familyGrouped?[{key:'familyGroup',order:'asc'}]:[]" ref="recordTable2" :db="db" collection="components" @reload="load" @notify="toast" v-table-scroll="'Component catalog'" data-workspace-table="Component catalog" label="Component catalog" :headers="[{title:'Component',key:'c0',sortable:true},{title:'Category',key:'c1',sortable:true},{title:'Specification Snapshot',key:'c2',sortable:true},{title:'Verification',key:'c3',sortable:true},{title:'Actions',key:'c4',sortable:false}]" :items="(components).map((c)=>({id:(c.id),record:(c),familyGroup:`${c.manufacturer||'Manufacturer unknown'} · ${c.family||'No family / series'}`,c0:(c.name),c1:(c.category),c2:(summary(c)),c3:(c.identityKind==='placeholder'?'Identity needed':c.verified?'Verified':'Needs verification'),c4:('')}))"><template #c0="{item:{record:c}}"><div><button type="button" class="table-name" :aria-label="c.model?componentIdentityLabel(c):c.name" @click="editComponent(c)">{{c.name}}</button><small>{{c.manufacturer||'Manufacturer not recorded'}}<template v-if="c.model"> · Model: {{c.model}}</template><template v-if="c.family"> · Family: {{c.family}}</template></small></div></template><template #c1="{item:{record:c}}"><div><span class="category-tag">{{c.category}}</span></div></template><template #c2="{item:{record:c}}"><div>{{summary(c)}}</div></template><template #c3="{item:{record:c}}"><div><span :class="['verification',c.verified?'verified':'']"><span />{{c.identityKind==='placeholder'?'Identity needed':c.verified?'Verified':'Needs verification'}}</span></div></template><template #c4="{item:{record:c}}"><div><v-btn v-if="c.identityKind==='placeholder'" variant="text" @click="identifySource=c.id">Identify uses</v-btn><v-btn variant="text" :icon="mdiTrashCanOutline" size="small" aria-label="Delete component" @click="confirmDelete={collection:'components',id:c.id,name:c.name}" /></div></template></RecordTable><div v-if="!components.length" class="empty-state"><h3>No matching components</h3><p>Add a component or adjust your filters.</p></div></section><div class="bottom-note"><v-icon aria-hidden="true" :icon="mdiInformationOutline" size="16" />Blank specification fields mean unknown, not zero. Click a component to edit its dimensions, slots and connectors.</div></template><CatalogMaintenance v-else ref="catalogMaintenance" :queue-jobs="catalogQueueJobs" :queue-running="catalogQueueRunning" :queue-loaded="catalogQueueLoaded" :refresh-queue="refreshCatalogQueue" embedded :view="catalogView" :db="db" :revision="revision" @view="v=>catalogView=v" @reload="load" @notify="toast" @edit-component="editComponent" @identify="id=>identifySource=id" />
    </template>

    <template v-else-if="page==='Equipment systems'">
     <div class="page-heading"><div><div class="eyebrow">BEYOND THE COMPUTER</div><h1>Equipment systems</h1><p>Define what each PC needs to connect to and control.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="editSystem()">Add equipment system</v-btn></div><v-text-field :model-value="search" @update:model-value="v=>search=String(v??'')" clearable placeholder="Search equipment systems…" :prepend-inner-icon="mdiMagnify" aria-label="Search equipment systems" hide-details class="system-search" />
     <div class="form-grid my-5"><v-autocomplete v-model="equipmentLocationFilter" label="Filter equipment by location" :items="equipmentLocationChoices" /><v-checkbox v-model="equipmentDescendants" label="Include descendant locations" hide-details /><v-checkbox v-model="equipmentGrouped" label="Group by location" hide-details /></div><section v-for="group in equipmentGroups" :key="group.id" class="mb-6"><h2 v-if="equipmentGrouped" class="mb-4">{{group.label}} <small>({{group.systems.length}})</small></h2><div class="systems-grid"><article v-for="s in group.systems" :key="s.id" class="panel system-card"><div class="system-card-head"><span class="config-icon"><v-icon aria-hidden="true" :icon="mdiLan" size="25" /></span><span class="neutral-badge">{{s.connections.length}} devices</span></div><h2>{{s.name}}</h2><button v-if="s.installationLocationId" type="button" class="table-name" @click="openRelated({kind:'location',id:s.installationLocationId})">{{equipmentLocation(s,db)}}</button><small v-else>{{equipmentLocation(s,db)}} · unlinked</small><p>{{s.description}}</p><div class="port-summary"><div v-for="(total,i) in connectionPortTotals(s.connections)" :key="i"><strong>{{total.quantity}}</strong><span>{{total.label}}</span></div></div><div class="device-tags"><span v-for="connection in s.connections" :key="connection.id">{{connection.name}}</span></div><div class="card-footer"><span>{{db.configurations.filter(c=>c.systemId===s.id).length}} linked builds</span><button type="button" @click="editSystem(s)">Edit requirements <v-icon aria-hidden="true" :icon="mdiArrowRight" size="16" /></button></div></article></div></section><div v-if="!systems.length" class="empty-state"><h3>No equipment systems found</h3><p>Add equipment and its connection requirements.</p></div>
    </template>

    <template v-else-if="page==='Installations'"><InstallationsWorkspace ref="installationsWorkspace" :db="db" :revision="revision" @reload="load" @notify="toast" @edit-pc="editPC" @edit-system="editSystem" @open-related="openRelated" /></template>
    <template v-else-if="page==='PC inventory' || page==='Component inventory'">
     <InventoryWorkspace ref="inventoryWorkspace" :key="page" :db="db" :revision="revision" :mode="page==='PC inventory'?'pcs':'stock'" @reload="load" @notify="toast" @edit-pc="editPC" @open-related="openRelated" />
    </template>

    <template v-else-if="page==='Storage planner'">
     <div class="page-heading"><div><div class="eyebrow">CAPACITY MEETS CONTINUITY</div><h1>Storage planner</h1><p>Compare boot pairs, data redundancy and how each drive is serviced.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="newConfig">New configuration</v-btn></div><section class="panel table-panel"><RecordTable ref="recordTable3" :db="db" collection="configurations" @reload="load" @notify="toast" v-table-scroll="'Storage plans'" data-workspace-table="Storage plans" label="Storage plans" :headers="[{title:'Configuration',key:'c0',sortable:true},{title:'Boot',key:'c1',sortable:true},{title:'Data Layout',key:'c2',sortable:true},{title:'Usable Data',key:'c3',sortable:true},{title:'Drive Locations',key:'c4',sortable:true},{title:'Actions',key:'c5',sortable:false}]" :items="(db.configurations).map((c)=>({id:(c.id),record:(c),c0:(c.name),c1:(c.storage.bootMirror?'Mirrored pair':'Independent'),c2:(c.storage.raid==='none'?'Independent':c.storage.raid.toUpperCase()),c3:(reports[c.id].usableDataGb),c4:([...new Set(c.placements.filter((p:Placement)=>part(p.componentId)?.category==='Drive').map((p:Placement)=>p.mount))].join(', ')),c5:('')}))"><template #c0="{item:{record:c}}"><div><button type="button" class="table-name" @click="openConfig(c);detailTab='storage'">{{c.name}}</button></div></template><template #c1="{item:{record:c}}"><div>{{c.storage.bootMirror?'Mirrored pair':'Independent'}}<small>{{capacity(knownCapacity(c,'boot',reports[c.id].bootGb))}}</small></div></template><template #c2="{item:{record:c}}"><div>{{c.storage.raid==='none'?'Independent':c.storage.raid.toUpperCase()}}</div></template><template #c3="{item:{record:c}}"><div>{{capacity(knownCapacity(c,'data',reports[c.id].usableDataGb))}}</div></template><template #c4="{item:{record:c}}"><div><span v-for="mount in [...new Set(c.placements.filter((p:Placement)=>part(p.componentId)?.category==='Drive').map((p:Placement)=>p.mount))]" :key="String(mount)" class="category-tag mr-1">{{mount}}</span></div></template><template #c5="{item:{record:c}}"><div><v-btn variant="text" :icon="mdiArrowTopRight" aria-label="Edit storage plan" @click="openConfig(c);detailTab='storage'" /></div></template></RecordTable></section>
    </template>

    <template v-else-if="page==='Data & imports'">
     <div class="page-heading"><div><div class="eyebrow">YOUR WORK. YOUR DATA.</div><h1>Data & imports</h1><p>Local SQLite storage with portable CSV imports, exports and complete backups.</p></div><v-btn variant="outlined" :prepend-icon="mdiDownload" href="/api/backup">Download JSON backup</v-btn></div><div class="data-grid"><section class="panel data-section"><h2>Export your workspace</h2><v-switch v-model="spreadsheetSafe" label="Spreadsheet-safe exports (disable for exact round-trip)" color="primary" /><p>Each collection is stored locally in SQLite and can be exported as CSV. Nested specifications, allocations and movement history use JSON inside CSV cells.</p><a v-for="collection in ['components','systems','requirementsSets','configurations','installationLocations','pcs','inventory']" :key="collection" :href="`/api/export/${collection}?spreadsheet=${spreadsheetSafe}`" class="export-row"><v-icon aria-hidden="true" :icon="mdiDatabaseOutline" size="20" /><div><strong>{{collection}}.csv</strong><small>Editable, round-trip compatible</small></div><v-icon aria-hidden="true" :icon="mdiDownload" size="20" /></a><a :href="`/api/export/movements?spreadsheet=${spreadsheetSafe}`" class="export-row"><v-icon aria-hidden="true" :icon="mdiDownload" size="20" /><div><strong>movements.csv</strong><small>Flat inventory movement history · export only</small></div><v-icon aria-hidden="true" :icon="mdiDownload" size="20" /></a></section><CsvImport :revision="revision" @reload="load" @notify="toast" @busy="v=>importing=v" /></div><section class="panel data-section control-stack mt-6"><h2>Restore a whole workspace</h2><p>Validate all collections together before replacing data. Restoration preserves the backup’s allocations and history and saves a safety copy of the current workspace.</p><v-file-input v-model="restoreFile" label="JSON backup" accept=".json,application/json" @update:model-value="restorePreview=null" /><v-btn variant="outlined" :disabled="!restoreFile" @click="previewRestore">Validate & preview</v-btn><template v-if="restorePreview"><p class="mt-4">Replacement record counts (including {{restorePreview.transitionPlans}} transition plans/drafts and {{restorePreview.archivedInventory||0}} deleted inventory records):</p><span v-for="(count,name) in restorePreview.counts" :key="name" class="category-tag mr-2">{{name}}: {{count}}</span><v-btn color="error" class="mt-4 d-block" :loading="busy" @click="commitRestore">Restore workspace</v-btn></template></section><section class="panel source-section"><span class="config-icon"><v-icon aria-hidden="true" :icon="mdiCubeOutline" size="25" /></span><div><h2>PCPartPicker page importer</h2><p>Convert locally saved PCPartPicker product HTML containing Product JSON-LD into a component CSV. The importer extracts name, brand and source; engineering specifications need manual verification.</p><code>pnpm import:pcpartpicker ./product.html --category CPU --output ./parts.csv</code><p class="source-note">No live database crawler is included. Saved pages without structured Product data will return a clear error. See the README for supported formats.</p></div></section>
    </template>
   </div>
  </v-main>

  <v-dialog scrollable :open-on-click="false" :activator="dialogOpeners.get('componentDraft')" @after-leave="restoreDialogFallback('componentDraft')" :model-value="!!componentDraft" @keydown.esc.stop.prevent="closeEditor('component')" aria-labelledby="component-editor-title" max-width="1120" persistent @update:model-value="v=>!v&&closeEditor('component')"><v-form ref="componentForm" class="component-dialog-form" :disabled="busy" validate-on="blur" @submit.prevent="saveComponent"><v-card v-if="componentDraft" class="editor-dialog component-dialog-card"><v-card-title class="dialog-head"><div><span class="eyebrow">COMPONENT CATALOG</span><h2 id="component-editor-title">{{db.components.some(c=>c.id===componentDraft?.id)?'Edit component':'Add component'}}</h2><p class="form-hint">{{componentDraft.name||'New model'}} · {{componentDraft.category}}</p></div><v-btn variant="text" :icon="mdiClose" aria-label="Close component editor" @click="closeEditor('component')" /></v-card-title><v-card-text class="dialog-body" :inert="busy"><ComponentDataEditor ref="componentDataEditor" :key="componentDraft.id" :component="componentDraft" :db="db" /></v-card-text><v-card-actions class="dialog-footer"><v-btn variant="text" @click="closeEditor('component')">Cancel</v-btn><span class="form-hint component-save-hint">All sections save together</span><v-spacer /><v-btn color="primary" :loading="busy" type="submit">Save component</v-btn></v-card-actions></v-card></v-form></v-dialog>
  <v-dialog scrollable :open-on-click="false" :activator="dialogOpeners.get('systemDraft')" @after-leave="restoreDialogFallback('systemDraft')" :model-value="!!systemDraft" @keydown.esc.stop.prevent="closeEditor('system')" aria-labelledby="system-editor-title" max-width="950" persistent><v-form ref="systemForm" :disabled="busy" validate-on="blur" @submit.prevent="saveSystem"><v-card v-if="systemDraft" class="editor-dialog"><v-card-title class="dialog-head"><div><span class="eyebrow">EQUIPMENT REQUIREMENTS</span><h2 id="system-editor-title">{{systemDraft.name||'New equipment system'}}</h2></div><v-btn variant="text" :icon="mdiClose" aria-label="Close system editor" @click="closeEditor('system')" /></v-card-title><v-card-text class="dialog-body" :inert="busy"><div class="form-grid"><v-text-field v-model="systemDraft.name" label="System name *" required :rules="[v=>!!String(v||'').trim()||'A name is required.']" /><v-autocomplete :model-value="systemDraft.installationLocationId||''" @update:model-value="v=>systemDraft!.installationLocationId=String(v??'')" label="Installation location" clearable :items="db.installationLocations.map(location=>({title:locationPath(location.id,db),value:location.id}))" hint="Link to any level of the location hierarchy." persistent-hint /><v-text-field v-model="systemDraft.location" label="Location notes / legacy label" /></div><v-textarea v-model="systemDraft.description" label="What this system controls" rows="2" class="mt-5" /><EngineeringEditor :system="systemDraft" :db="db" /><v-btn v-if="db.systems.some(s=>s.id===systemDraft?.id)" variant="text" color="error" :prepend-icon="mdiTrashCanOutline" @click="confirmDelete={collection:'systems',id:systemDraft.id,name:systemDraft.name};systemDraft=null">Delete equipment system</v-btn></v-card-text><v-card-actions class="dialog-footer"><v-btn variant="text" @click="closeEditor('system')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!systemDraft.name.trim()" type="submit">Save requirements</v-btn></v-card-actions></v-card></v-form></v-dialog>
  <v-dialog scrollable :open-on-click="false" :activator="dialogOpeners.get('pcDraft')" @after-leave="restoreDialogFallback('pcDraft')" :model-value="!!pcDraft" @keydown.esc.stop.prevent="closeEditor('pc')" aria-labelledby="pc-editor-title" max-width="760" persistent><v-form ref="pcForm" :disabled="busy" validate-on="blur" @submit.prevent="savePC"><v-card v-if="pcDraft" class="editor-dialog"><v-card-title class="dialog-head"><h2 id="pc-editor-title">{{pcDraft.name||'Register PC'}}</h2><v-btn variant="text" :icon="mdiClose" aria-label="Close PC editor" @click="closeEditor('pc')" /></v-card-title><v-card-text class="dialog-body" :inert="busy"><v-text-field v-model="pcDraft.name" label="PC / asset name *" required :rules="[v=>!!String(v||'').trim()||'A name is required.']" class="mb-5" /><div class="form-grid"><v-text-field v-model="pcDraft.serial" label="Serial number" /><v-text-field v-model="pcDraft.location" label="Location" /></div><v-autocomplete v-model="pcDraft.configurationId" label="Planned configuration" :items="[{title:'Unassigned',value:''},...db.configurations.map(c=>({title:c.name,value:c.id}))]" class="my-5" /><v-autocomplete v-model="pcDraft.installationLocationId" label="Physical installation location" :items="[{title:'Unassigned',value:''},...db.installationLocations.filter(l=>isPCInstallationKind(l.kind)).map(l=>({title:locationPath(l.id,db),value:l.id}))]" class="my-5" @update:model-value="selectPCLocation" /><p class="form-hint">Installed parts are located at the assigned installation. The free-text location remains available for unregistered places and service notes.</p><HardwareSurveyEditor :pc="pcDraft" :db="db" /><v-textarea v-model="pcDraft.notes" label="Installation / asset notes" rows="2" /><div class="spec-heading"><h3>Recorded equipment & storage settings</h3><v-btn variant="outlined" size="small" :disabled="!pcDraft.configurationId" @click="captureTemplateSettings()">Copy template settings</v-btn></div><p class="form-hint">The template is a plan. Installed parts are recorded through inventory allocations. These settings are captured for this PC and do not change when the template changes.</p><v-btn v-if="!pcDraft.buildSettings" variant="outlined" @click="pcDraft.buildSettings={systemId:'',storage:{raid:'none',bootMirror:false},notes:'',portMappings:[]}">Enter build settings</v-btn><template v-else><div class="form-grid"><v-autocomplete v-model="pcDraft.buildSettings.requirementSetId" label="Recorded installation requirements set" :items="requirementChoices" @update:model-value="selectPCRequirements" /><v-select v-if="pcDraft.buildSettings.requirementSetId" v-model="pcDraft.buildSettings.requirementRevision" label="Recorded requirements revision" :items="requirementRevisions(pcDraft.buildSettings.requirementSetId)" @update:model-value="updatePCRequirements" /><v-autocomplete v-model="pcDraft.buildSettings.systemId" label="Recorded equipment system" :items="[{title:'No equipment linked',value:''},...db.systems.map(s=>({title:s.name,value:s.id}))]" /><v-select v-model="pcDraft.buildSettings.storage.raid" label="Recorded data redundancy" :items="['none','mirror','raid5','raid6','raid10']" /></div><v-switch v-model="pcDraft.buildSettings.storage.bootMirror" label="Recorded boot mirror" color="primary" hide-details /><v-textarea v-model="pcDraft.buildSettings.notes" label="Recorded configuration / driver notes" rows="2" class="mt-4" /></template><EngineeringEditor v-if="pcSettingsConfiguration" :configuration="pcSettingsConfiguration" :db="db" settings-only /><PcLifecycleEditor :pc="pcDraft" :db="db" /><v-btn v-if="db.pcs.some(p=>p.id===pcDraft?.id)" variant="text" color="error" :prepend-icon="mdiTrashCanOutline" class="mt-5" @click="confirmDelete={collection:'pcs',id:pcDraft.id,name:pcDraft.name};pcDraft=null">Delete PC</v-btn></v-card-text><v-card-actions class="dialog-footer"><v-btn variant="text" @click="closeEditor('pc')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!pcDraft.name.trim()" type="submit">Save PC</v-btn></v-card-actions></v-card></v-form></v-dialog>
  <v-dialog scrollable :open-on-click="false" :activator="dialogOpeners.get('delete')" @after-leave="restoreDialogFallback('delete')" :model-value="!!confirmDelete" @update:model-value="v=>!v&&(confirmDelete=null)" @keydown.esc.stop.prevent="confirmDelete=null" aria-labelledby="delete-editor-title" max-width="440"><v-card class="editor-dialog"><v-card-text class="dialog-body" :inert="busy"><h2 id="delete-editor-title">Delete {{confirmDelete?.name}}?</h2><p class="mt-4">This removes the record from the local database. Records referenced by other records cannot be deleted.</p><v-alert v-if="deleteComponentUses.length" :type="deleteBlockingUses.length?'warning':'info'" variant="tonal" class="mt-4"><strong>{{deleteBlockingUses.length?'This component is still in use.':'Empty stock records will be archived.'}}</strong><p v-if="deleteComponentUses.length!==deleteBlockingUses.length">Deleting this type will also archive its empty stock records and retain their history and component specifications.</p><v-btn variant="text" @click="mergeSources=[confirmDelete!.id];confirmDelete=null">Merge into another component type</v-btn><ul><li v-for="use in deleteComponentUses" :key="`${use.kind}:${use.id}`"><v-btn variant="text" class="text-wrap" @click="openDeleteReference(use)">{{use.name}} ({{use.id}})</v-btn><p>{{use.detail}}</p><v-btn v-if="emptyStockReference(use)" variant="outlined" :disabled="busy" :loading="busy" @click="archiveEmptyReference(use)">Delete empty inventory record</v-btn></li></ul></v-alert></v-card-text><v-card-actions class="dialog-footer"><v-btn variant="text" @click="confirmDelete=null">Cancel</v-btn><v-btn color="error" variant="flat" :loading="busy" :disabled="!!deleteBlockingUses.length" @click="deleteRecord">Delete</v-btn></v-card-actions></v-card></v-dialog>
  <ComponentIdentificationDialog ref="identifyEditor" :source-id="identifySource" :db="db" :revision="revision" @close="identifySource=null" @reload="load" @notify="toast" /><ComponentMergeDialog ref="mergeEditor" :source-ids="mergeSources" :db="db" :revision="revision" @close="mergeSources=null" @reload="load" @notify="toast" /><v-snackbar-queue v-model="notices" :timeout="6000" color="primary" closable />
 </v-app>
</template>
